/// Processes a scenario's steps in order and reports one result per step.
pub fn run_scenario(scenario: &str) -> Result<Vec<StepResult>, String> {
    let scenario: Scenario = serde_json::from_str(scenario).map_err(|error| error.to_string())?;
    let customer = Customer {
        years_with_mhpco: scenario.customer.years_with_mhpco,
    };
    let mut results = Vec::new();
    let mut policies: Vec<Vec<Item>> = Vec::new();
    for step in &scenario.steps {
        let result = match step {
            Step::Quote { items } => {
                let items = insured_items_of(items);
                let history = CustomerHistory {
                    customer: &customer,
                    preceding_contracts: 0,
                };
                let premium = quote(&history, &items)?;
                policies.push(items);
                StepResult::Quote { premium }
            }
            Step::Claim { policy, incident } => {
                let insured_items = policies
                    .get(*policy)
                    .ok_or_else(|| format!("no policy was created by step {policy}"))?;
                let damages = reported_damages_of(&incident.damages);
                let settlement = claim(insured_items, 0, &damages)?;
                StepResult::Claim {
                    payout: settlement.payout,
                    remaining_cap: settlement.remaining_cap,
                }
            }
        };
        results.push(result);
    }
    Ok(results)
}

